import {
    Component,
    ElementRef,
    OnChanges,
    OnInit,
    SimpleChanges,
    computed,
    input,
    viewChild,
} from '@angular/core';
import { humanReadableByteCount } from '@placeos/ts-client';

import { Point } from '../../common/types';
import { BasicLineGraphComponent } from '../../ui/basic-line-graph.component';
import { TranslatePipe } from '../../ui/translate.pipe';

interface PlaceClusterRunCounts {
    modules: number;
    drivers: number;
}

export interface PlaceClusterNode {
    hostname: string;
    cpu_count: number;
    core_cpu: number;
    total_cpu: number;
    memory_total: number;
    memory_usage: number;
    core_memory: number;
    run_count?: PlaceClusterRunCounts;
}

export interface PlaceClusterUsageStamp {
    id: number;
    cpu: number;
    memory: number;
}

@Component({
    selector: 'admin-cluster-node',
    template: `
        @if (show_name()) {
            <h4>{{ node()?.hostname }}</h4>
        }
        <div class="border-base-300 mb-2 h-36 w-full rounded-sm border p-2">
            <div basic-line-graph [lines]="lines" class="h-full w-full"></div>
        </div>
        <div class="memory-utilisation">
            <div class="flex space-x-2">
                <div
                    class="border-base-300 flex flex-1 flex-col items-center justify-center space-y-1 rounded-sm border p-1"
                >
                    <div>{{ 'ADMIN.CLUSTERS_CPU_USAGE' | translate }}</div>
                    <div class="mono text-4xl font-medium">
                        {{ node()?.total_cpu.toFixed(0) }}%
                    </div>
                    <div class="mono w-36 text-center text-xs">
                        {{
                            'ADMIN.CLUSTERS_CPU_CORES'
                                | translate: { count: node()?.cpu_count || 0 }
                        }}
                    </div>
                </div>
                <div
                    class="border-base-300 flex flex-1 flex-col items-center justify-center space-y-1 rounded-sm border p-1"
                >
                    <div>{{ 'ADMIN.CLUSTERS_MEMORY_USAGE' | translate }}</div>
                    <div class="mono text-4xl font-medium">
                        {{ memory_percentage().toFixed(0) }}%
                    </div>
                    <div class="mono w-36 text-center text-xs">
                        {{ used_memory() }}/{{ total_memory() }}
                    </div>
                </div>
            </div>
        </div>
    `,
    styles: [],
    imports: [TranslatePipe, BasicLineGraphComponent],
})
export class AdminClusterNodeComponent implements OnChanges, OnInit {
    public readonly show_name = input(true);
    /** Node to display on the view */
    public readonly node = input<PlaceClusterNode>(undefined);
    /** Historical data for node */
    public readonly history = input<PlaceClusterUsageStamp[]>(undefined);
    /** Store for the chart data object */
    // private _chart: Chart;
    /**  */
    public lines: Point[][] = [];

    public readonly used_memory = computed(() => {
        return humanReadableByteCount((this.node()?.memory_usage || 0) * 1024)
            .replace('GB', '')
            .replace('MB', '')
            .trim();
    });

    public readonly total_memory = computed(() => {
        return humanReadableByteCount((this.node()?.memory_total || 0) * 1024);
    });

    public readonly memory_percentage = computed(() => {
        return (
            ((this.node()?.memory_usage || 0) /
                (this.node()?.memory_total || 1)) *
            100
        );
    });

    public readonly _chart_el =
        viewChild<ElementRef<HTMLCanvasElement>>('chart');

    public ngOnInit() {
        this.generateCharts();
    }

    public ngOnChanges(changes: SimpleChanges) {
        if (changes.history && this.history()) {
            this.generateCharts();
        }
    }

    public generateCharts(): void {
        this.lines = [
            this.history().map(({ cpu }, idx) => ({ x: idx, y: cpu })),
            this.history().map(({ memory }, idx) => ({ x: idx, y: memory })),
        ];
    }
}
